#!/usr/bin/env python3
"""Fixed-width hash-input regression for the pure-Python SRP backend.

Every expected digest in this file is computed by the small, self-contained
reference implementation below (RFC 5054 section 2.5/2.6 ``PAD()`` plus the
plain modular arithmetic of SRP-6a).  The library under test is never used
to produce an expectation, so a library that encodes a transcript
differently from the selected compatibility mode cannot make the test pass
by "agreeing with itself".

Run directly (``python srp/test_fixed_width.py``) or through unittest.
"""

import hashlib
import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from srp import _pysrp as srp


SALT = bytes.fromhex("00BEB25379D1A8581EB5A727673A2441EE")  # deliberate leading zero
USERNAME = b"alice"
PASSWORD = b"password123"


def sha1(data):
    return hashlib.sha1(data).digest()


def minimal(value):
    """Minimal big-endian encoding of an integer (pysrp default mode)."""
    length = (value.bit_length() + 7) // 8
    return value.to_bytes(length or 1, "big")


class Rfc5054Reference(object):
    """SRP-6a transcript built only from the RFC 5054 width rules.

    ``mode == "rfc"`` left-pads every integer that enters a hash to the
    byte length of N (RFC 5054 ``PAD()``).  ``mode == "legacy"`` keeps the
    minimal encoding, which is the historical pysrp default.
    """

    def __init__(self, n, g, mode):
        self.N = n
        self.g = g
        self.mode = mode
        self.width = (n.bit_length() + 7) // 8

    def encode(self, value):
        if self.mode == "rfc":
            return value.to_bytes(self.width, "big")
        return minimal(value)

    def k(self):
        return int.from_bytes(sha1(self.encode(self.N) + self.encode(self.g)), "big")

    def x(self, salt=SALT, username=USERNAME, password=PASSWORD):
        inner = sha1(username + b":" + password)
        return int.from_bytes(sha1(salt + inner), "big")

    def v(self, salt=SALT, username=USERNAME, password=PASSWORD):
        return pow(self.g, self.x(salt, username, password), self.N)

    def u(self, A, B):
        return int.from_bytes(sha1(self.encode(A) + self.encode(B)), "big")

    def S(self, A, B, a, b, v):
        return pow(A * pow(v, self.u(A, B), self.N), b, self.N)

    def K(self, S):
        return sha1(minimal(S))

    def h_n_xor_h_g(self):
        return bytes(a ^ b for a, b in zip(sha1(minimal(self.N)), sha1(self.encode(self.g))))

    def M(self, salt, A, B, K):
        return sha1(self.h_n_xor_h_g() + sha1(USERNAME) + salt +
                    self.encode(A) + self.encode(B) + K)

    def H_AMK(self, A, M, K):
        return sha1(self.encode(A) + M + K)


